7	/// Perform state-based actions without a registry (for backward compat with tests).
8	/// Uses raw P/T values only.
9	pub fn check_state_based_actions(state: &mut GameState) -> bool {
10	    check_state_based_actions_with_registry(state, None)
11	}
12	
13	/// Perform state-based actions. Returns true if any were performed.
14	/// Per rule 704.3, this is called repeatedly until no actions are taken.
15	pub fn check_state_based_actions_with_registry(state: &mut GameState, registry: Option<&CardRegistry>) -> bool {
16	    let mut any_action = false;
17	
18	    loop {
19	        let mut took_action = false;
20	
21	        // Rule 704.5a: A player with 0 or less life loses the game.
22	        for i in 0..state.players.len() {
23	            let (lost, life, id) = {
24	                let p = &state.players[i];
25	                (p.lost, p.life, p.id)
26	            };
27	            if !lost && life <= 0 {
28	                state.players[i].lost = true;
29	                state.events.push(GameEvent::PlayerLost {
30	                    player: id,
31	                    reason: LossReason::LifeReachedZero,
32	                });
33	                took_action = true;
34	            }
35	        }
36	
37	        // Rule 704.5b: A player who attempted to draw from an empty library loses.
38	        for i in 0..state.players.len() {
39	            let (lost, drawn_empty, id) = {
40	                let p = &state.players[i];
41	                (p.lost, p.has_drawn_from_empty, p.id)
42	            };
43	            if !lost && drawn_empty {
44	                state.players[i].lost = true;
45	                state.events.push(GameEvent::PlayerLost {
46	                    player: id,
47	                    reason: LossReason::DrewFromEmptyLibrary,
48	                });
49	                took_action = true;
50	            }
51	        }
52	
53	        // Identify creatures that need to leave the battlefield.
54	        let creature_ids: Vec<_> = state.objects.values()
55	            .filter(|o| o.zone == Zone::Battlefield && o.power.is_some())
56	            .map(|o| o.id)
57	            .collect();
58	
59	        // Classify each creature: zero toughness vs lethal damage/deathtouch.
60	        let mut zero_toughness_ids = Vec::new();
61	        let mut destroyed_ids = Vec::new();
62	
63	        for id in creature_ids {
64	            let effective_t = registry
65	                .and_then(|r| state.effective_toughness(id, r))
66	                .or_else(|| state.get_object(id).and_then(|o| o.toughness));
67	            let obj = state.get_object(id);
68	            let damage = obj.map(|o| o.damage_marked).unwrap_or(0);
69	            let deathtouch = obj.map(|o| o.dealt_deathtouch_damage).unwrap_or(false);
70	            match effective_t {
71	                Some(t) if t <= 0 => {
72	                    // Rule 704.5f: 0 or less toughness — not destruction,
73	                    // indestructible and regeneration do NOT prevent this.
74	                    zero_toughness_ids.push(id);
75	                }
76	                Some(t) if (damage as i32) >= t || (deathtouch && damage > 0) => {
77	                    // Rules 704.5g/h: lethal damage or deathtouch — destruction,
78	                    // checked via try_destroy (indestructible / regeneration apply).
79	                    destroyed_ids.push(id);
80	                }
81	                _ => {}
82	            }
83	        }
84	
85	        // Rule 704.5f: zero toughness goes directly to graveyard.
86	        for id in zero_toughness_ids {
87	            let (cid, ctrl, damaged_by) = state.get_object(id)
88	                .map(|o| (o.card_id, o.controller, o.damaged_by.clone()))
89	                .unwrap_or((crate::ids::CardId(0), crate::ids::PlayerId(0), Vec::new()));
90	            let last_known_toughness = registry
91	                .and_then(|r| state.effective_toughness(id, r))
92	                .or_else(|| state.get_object(id).and_then(|o| o.toughness))
93	                .unwrap_or(0);
94	            state.events.push(GameEvent::CreatureDied { object: id, card_id: cid, controller: ctrl, damaged_by, last_known_toughness });
95	            state.move_object(id, Zone::Graveyard);
96	            state.creature_died_this_turn = true;
97	            took_action = true;
98	        }
99	
100	        // Rules 704.5g/h: lethal damage or deathtouch — use destruction pipeline.
101	        for id in destroyed_ids {
102	            if let Some(reg) = registry {
103	                use crate::destruction::DestroyResult;
104	                // Full pipeline: indestructible check + regeneration.
105	                match crate::destruction::try_destroy(state, id, reg) {
106	                    DestroyResult::Died => {
107	                        took_action = true;
108	                    }
109	                    DestroyResult::Regenerated => {
110	                        // State changed (damage cleared, tapped), so next
111	                        // SBA pass won't re-identify this creature.
112	                        took_action = true;
113	                        continue;
114	                    }
115	                    DestroyResult::Indestructible => {
116	                        // No state change — don't set took_action to avoid
117	                        // infinite loop (creature still has lethal damage).
118	                        continue;
119	                    }
120	                }
121	            } else {
122	                // No registry (legacy tests): skip indestructible check,
123	                // but still handle regeneration shields inline.
124	                let shields = state.get_object(id).map(|o| o.regeneration_shields).unwrap_or(0);
125	                if shields > 0 {
126	                    crate::destruction::remove_from_combat(state, id);
127	                    if let Some(obj) = state.get_object_mut(id) {
128	                        obj.tapped = true;
129	                        obj.damage_marked = 0;
130	                        obj.dealt_deathtouch_damage = false; obj.damaged_by.clear();
131	                        obj.regeneration_shields -= 1;
132	                    }
133	                    state.log(LogLevel::Event, format!("{} regenerated",
134	                        state.get_object(id).map(|o| o.name.as_str()).unwrap_or("?")));
135	                    took_action = true;
136	                    continue;
137	                }
138	                let (cid, ctrl, damaged_by) = state.get_object(id)
139	                    .map(|o| (o.card_id, o.controller, o.damaged_by.clone()))
140	                    .unwrap_or((crate::ids::CardId(0), crate::ids::PlayerId(0), Vec::new()));
141	                let last_known_toughness = state.get_object(id).and_then(|o| o.toughness).unwrap_or(0);
142	                state.events.push(GameEvent::CreatureDied { object: id, card_id: cid, controller: ctrl, damaged_by, last_known_toughness });
143	                state.move_object(id, Zone::Graveyard);
144	                state.creature_died_this_turn = true;
145	                took_action = true;
146	            }
147	        }
148	
149	        // Rule 704.5m: Aura not attached to anything goes to graveyard.
150	        // Curses attached to players (attached_to_player) are exempt.
151	        // Equipment stays on the battlefield when unattached (detaches instead).
152	        let unattached_auras: Vec<_> = state.objects.values()
153	            .filter(|o| {
154	                o.zone == Zone::Battlefield
155	                    && o.attached_to.is_some()
156	                    && o.attached_to_player.is_none() // player-attached curses are fine
157	                    && !o.is_equipment // equipment stays on battlefield when unattached
158	                    && {
159	                        let target_id = o.attached_to.expect("aura must have attached_to");
160	                        state.get_object(target_id)
161	                            .map(|t| t.zone != Zone::Battlefield)
162	                            .unwrap_or(true) // target doesn't exist
163	                    }
164	            })
165	            .map(|o| o.id)
166	            .collect();
167	
168	        // Equipment attached to creatures that left the battlefield: detach (don't destroy).
169	        let detach_equipment: Vec<ObjectId> = state.objects.values()
170	            .filter(|o| {
171	                o.zone == Zone::Battlefield
172	                    && o.is_equipment
173	                    && o.attached_to.is_some()
174	                    && {
175	                        let target_id = o.attached_to.expect("equipment must have attached_to");
176	                        state.get_object(target_id)
177	                            .map(|t| t.zone != Zone::Battlefield)
178	                            .unwrap_or(true)
179	                    }
180	            })
181	            .map(|o| o.id)
182	            .collect();
183	        for id in detach_equipment {
184	            if let Some(obj) = state.get_object_mut(id) {
185	                obj.attached_to = None;
186	            }
187	            took_action = true;
188	        }
189	
190	        for id in unattached_auras {
191	            state.move_object(id, Zone::Graveyard);
192	            took_action = true;
193	        }
194	
195	        // Rule 704.5q: +1/+1 and -1/-1 counters annihilate in pairs.
196	        let counter_targets: Vec<_> = state.objects.values()
197	            .filter(|o| {
198	                o.zone == Zone::Battlefield
199	                    && *o.counters.get(&crate::types::CounterType::PlusOnePlusOne).unwrap_or(&0) > 0
200	                    && *o.counters.get(&crate::types::CounterType::MinusOneMinusOne).unwrap_or(&0) > 0
201	            })
202	            .map(|o| o.id)
203	            .collect();
204	        for id in counter_targets {
205	            if let Some(obj) = state.objects.get_mut(&id) {
206	                let plus = *obj.counters.get(&crate::types::CounterType::PlusOnePlusOne).unwrap_or(&0);
207	                let minus = *obj.counters.get(&crate::types::CounterType::MinusOneMinusOne).unwrap_or(&0);
208	                let annihilate = plus.min(minus);
209	                *obj.counters.entry(crate::types::CounterType::PlusOnePlusOne).or_insert(0) -= annihilate;
210	                *obj.counters.entry(crate::types::CounterType::MinusOneMinusOne).or_insert(0) -= annihilate;
211	                took_action = true;
212	            }
213	        }
214	
215	        // Rule 704.5i: A planeswalker with 0 or less loyalty goes to graveyard.
216	        let pw_zero_loyalty: Vec<_> = state.objects.values()
217	            .filter(|o| {
218	                o.zone == Zone::Battlefield
219	                    && o.card_types.contains(&crate::types::CardType::Planeswalker)
220	                    && *o.counters.get(&crate::types::CounterType::Loyalty).unwrap_or(&0) == 0
221	            })
222	            .map(|o| o.id)
223	            .collect();
224	        // Also check via registry for non-token planeswalkers.
225	        let pw_zero_loyalty_registry: Vec<_> = if let Some(reg) = registry {
226	            state.objects.values()
227	                .filter(|o| {
228	                    o.zone == Zone::Battlefield
229	                        && !o.card_types.contains(&crate::types::CardType::Planeswalker)
230	                        && reg.card_data(o.card_id)
231	                            .map(|d| d.card_types.contains(&crate::types::CardType::Planeswalker))
232	                            .unwrap_or(false)
233	                        && *o.counters.get(&crate::types::CounterType::Loyalty).unwrap_or(&0) == 0
234	                })
235	                .map(|o| o.id)
236	                .collect()
237	        } else {
238	            vec![]
239	        };
240	        for id in pw_zero_loyalty.into_iter().chain(pw_zero_loyalty_registry) {
241	            state.log(LogLevel::Event, format!("{} has 0 loyalty and is put into graveyard",
242	                state.get_object(id).map(|o| o.name.as_str()).unwrap_or("?")));
243	            state.move_object(id, Zone::Graveyard);
244	            took_action = true;
245	        }
246	
247	        // State-triggered abilities (CR 603.8): checked during SBA processing.
248	        // When the condition is met and the trigger is not already on the stack,
249	        // push a trigger onto pending_triggers so it goes on the stack and can
250	        // be responded to. The trigger won't fire again while it's on the stack.
251	        if let Some(reg) = registry {
252	            let garruk_card_id = reg.get_id_by_name("Garruk Relentless");
253	            if let Some(gid) = garruk_card_id {
254	                let garruk_to_trigger: Vec<_> = state.objects.values()
255	                    .filter(|o| {
256	                        o.zone == Zone::Battlefield
257	                            && o.card_id == gid
258	                            && !o.is_transformed
259	                            && !o.state_trigger_on_stack
260	                            && *o.counters.get(&crate::types::CounterType::Loyalty).unwrap_or(&0) <= 2
261	                    })
262	                    .map(|o| (o.id, o.controller))
263	                    .collect();
264	                for (id, controller) in garruk_to_trigger {
265	                    if let Some(obj) = state.get_object_mut(id) {
266	                        obj.state_trigger_on_stack = true;
267	                    }
268	                    state.pending_triggers.push(
269	                        crate::triggers::PendingTrigger::StateTriggered {
270	                            object_id: id,
271	                            card_id: gid,
272	                            controller,
273	                            description: "When Garruk Relentless has two or fewer loyalty counters on him, transform him".into(),
274	                        }
275	                    );
276	                    state.log(LogLevel::Event,
277	                        "Garruk Relentless's state-triggered ability triggers (transform)".into());
278	                    took_action = true;
279	                }
280	            }
281	        }
282	
283	        // Rule 704.5k: Legend rule — if a player controls two or more legendary
284	        // permanents with the same name, all are put into the graveyard.
285	        // (Simplified: keep the newest, remove the rest.)
286	        {
287	            use std::collections::HashMap as Map;
288	            let mut legend_groups: Map<(crate::ids::PlayerId, String), Vec<crate::ids::ObjectId>> = Map::new();
289	            for obj in state.objects.values() {
290	                if obj.zone == Zone::Battlefield && obj.is_legendary {
291	                    legend_groups.entry((obj.controller, obj.name.clone()))
292	                        .or_default()
293	                        .push(obj.id);
294	                }
295	            }
296	            for (_, ids) in legend_groups {
297	                if ids.len() > 1 {
298	                    // Keep the first (oldest), remove the rest.
299	                    for &id in &ids[1..] {
300	                        state.move_object(id, Zone::Graveyard);
301	                        took_action = true;
302	                    }
303	                }
304	            }
305	        }
306	
307	        // Rule 704.5d: A token not on the battlefield ceases to exist.
308	        let dead_tokens: Vec<_> = state.objects.values()
309	            .filter(|o| o.is_token && o.zone != Zone::Battlefield)
310	            .map(|o| o.id)
311	            .collect();
312	        for id in dead_tokens {
313	            state.objects.remove(&id);
314	            took_action = true;
315	        }
316	
317	        // Check for game end: only one (or zero) players alive.
318	        let alive: Vec<_> = state.players.iter().filter(|p| !p.lost).collect();
319	        if alive.len() <= 1 && state.result.is_none() {
320	            let result = if alive.len() == 1 {
321	                GameResult::Winner(alive[0].id)
322	            } else {
323	                GameResult::Draw
324	            };
325	            state.events.push(GameEvent::GameEnded { result: result.clone() });
326	            state.result = Some(result);
327	            took_action = true;
328	        }
329	
330	        if !took_action {
331	            break;
332	        }
333	        any_action = true;
334	    }
335	
336	    any_action
337	}
