1	use crate::actions::Target;
2	use crate::cards::{ActivatedAbilityDef, CardBehavior, CardData, CardRegistry, SacrificeCost};
3	use crate::ids::ObjectId;
4	use crate::state::GameState;
5	use crate::types::*;
6	
7	/// Mirror-Mad Phantasm {3}{U}{U} 5/1 Spirit with Flying.
8	/// {1}{U}: Mirror-Mad Phantasm's owner shuffles it into their library. If that player does,
9	/// they reveal cards from the top of their library until they reveal a card named Mirror-Mad
10	/// Phantasm, put that card onto the battlefield, and put all other cards revealed this way
11	/// into their graveyard.
12	///
13	/// Simplified: Shuffle into library, then mill until we find Mirror-Mad Phantasm (or run out).
14	/// If found, put it on the battlefield. All others go to graveyard.
15	pub struct MirrorMadPhantasm;
16	
17	impl CardBehavior for MirrorMadPhantasm {
18	    fn card_data(&self) -> CardData {
19	        CardData {
20	            name: "Mirror-Mad Phantasm".into(),
21	            cost: Some(ManaCost::new(vec![
22	                ManaSymbol::Generic(3),
23	                ManaSymbol::Colored(Color::Blue),
24	                ManaSymbol::Colored(Color::Blue),
25	            ])),
26	            card_types: vec![CardType::Creature],
27	            supertypes: vec![],
28	            subtypes: vec!["Spirit".into()],
29	            power: Some(5),
30	            toughness: Some(1),
31	            oracle_text: "Flying\n{1}{U}: Mirror-Mad Phantasm's owner shuffles it into their library. If that player does, they reveal cards from the top of their library until they reveal a card named Mirror-Mad Phantasm, put that card onto the battlefield, and put all other cards revealed this way into their graveyard.".into(),
32	            keywords: vec![Keyword::Flying],
33	            flashback_cost: None,
34	            continuous_effects: vec![],
35	            additional_cost: None,
36	            triggered_abilities: vec![],
37	        }
38	    }
39	
40	    fn activated_abilities(&self, state: &GameState, object_id: ObjectId, _registry: &CardRegistry) -> Vec<ActivatedAbilityDef> {
41	        match state.get_object(object_id) {
42	            Some(o) if o.zone == Zone::Battlefield => {}
43	            _ => return vec![],
44	        };
45	
46	        vec![ActivatedAbilityDef {
47	            ability_index: 0,
48	            description: "{1}{U}: Shuffle into library, reveal until Mirror-Mad Phantasm, mill the rest".into(),
49	            cost: ManaCost::new(vec![
50	                ManaSymbol::Generic(1),
51	                ManaSymbol::Colored(Color::Blue),
52	            ]),
53	            requires_tap: false,
54	            sacrifice_cost: SacrificeCost::None,
55	            target_requirement: None,
56	            once_per_turn: false,
57	            sorcery_speed_only: false,
58	        }]
59	    }
60	
61	    fn on_activate_ability(&self, state: &mut GameState, object_id: ObjectId, _ability_index: usize, _targets: &[Target], _registry: &CardRegistry) {
62	        let owner = match state.get_object(object_id) {
63	            Some(o) => o.owner,
64	            None => return,
65	        };
66	
67	        // "shuffles it into their library" — move to library zone, add to library order,
68	        // then shuffle so the card is at a random position before the reveal loop.
69	        state.move_object(object_id, Zone::Library);
70	        state.get_player_mut(owner).library_order.push(object_id);
71	        {
72	            use rand::seq::SliceRandom;
73	            let mut rng = rand::thread_rng();
74	            state.get_player_mut(owner).library_order.shuffle(&mut rng);
75	        }
76	
77	        state.log(crate::state::LogLevel::Event,
78	            "Mirror-Mad Phantasm shuffled into library".into());
79	
80	        // Reveal cards from the top until we find Mirror-Mad Phantasm.
81	        let mut milled = Vec::new();
82	        let mut found = None;
83	        loop {
84	            let top = state.get_player_mut(owner).draw_top_card();
85	            match top {
86	                Some(card_id) => {
87	                    let name = state.get_object(card_id).map(|o| o.name.clone()).unwrap_or_default();
88	                    if name == "Mirror-Mad Phantasm" {
89	                        found = Some(card_id);
90	                        break;
91	                    } else {
92	                        milled.push(card_id);
93	                    }
94	                }
95	                None => break, // Library empty.
96	            }
97	        }
98	
99	        // Put all milled cards into graveyard.
100	        for card_id in &milled {
101	            state.move_object(*card_id, Zone::Graveyard);
102	        }
